#include <iostream>
#include <vector>
using namespace std;

struct Task {
    string name;
    int steps, current;
    void (*action)(const string&, int);
};

void print_step(const string& name, int step) {
    cout << name << " step " << step << endl;
}

int main() {
    vector<Task> tasks = {{"Task1", 5, 0, print_step}, {"Task2", 3, 0, print_step}, {"Task3", 4, 0, print_step}};
    bool done;
    do {
        done = true;
        for (auto& t : tasks) {
            if (t.current < t.steps) {
                t.action(t.name, t.current++);
                done = false;
            }
        }
    } while (!done);
    return 0;
}
